"""Private, offline review of a verified local ledger; no personal risk scores."""
import html,json
from pathlib import Path
from engine import Engine,now

def invoice_evidence(engine,findings):
 """Resolve referenced Excel rows from verified immutable cuts, never live files."""
 requests={}
 for finding in findings:
  ev=finding['evidence']
  for hash_,rows in [(ev.get('current_source_sha256'),ev.get('source_rows',[])),(ev.get('previous',{}).get('source_sha256'),ev.get('previous',{}).get('source_rows',[]))]:
   if hash_:requests.setdefault(hash_,set()).update(rows)
 resolved={}
 for hash_,wanted in requests.items():
  entry=engine.db.execute('SELECT object_path FROM snapshots WHERE hash=?',(hash_,)).fetchone()
  if not entry:raise ValueError('Evidence source is absent from the verified catalog')
  cut=json.loads((engine.root/entry[0]).read_text(encoding='utf-8'))
  resolved[hash_]={'provenance':cut.get('provenance',{}),'scope':cut['scope'],'rows':{str(r['source_row']):dict(zip(cut['headers'],r['cells'])) for r in cut['rows'] if r['source_row'] in wanted}}
  if set(map(int,resolved[hash_]['rows']))!=wanted:raise ValueError('Evidence references an absent source row')
 return resolved

def export_report(runtime,output):
 with Engine(runtime) as e:
  head=e.verify();run=e.db.execute('SELECT * FROM runs ORDER BY at DESC LIMIT 1').fetchone()
  if not run:raise ValueError('No accepted audit run exists')
  findings=json.loads(run['findings_json']);reviews={};coverage={}
  for r in e.db.execute('SELECT event_json FROM events ORDER BY seq'):
   event=json.loads(r[0]);p=event['payload']
   if event['action']=='finding.reviewed' and p['run_id']==run['id']:reviews[p['fingerprint']]={**p,'actor':event['actor'],'at':event['at']}
   if event['action']=='audit.completed' and p['run_id']==run['id']:coverage=p.get('summary',{})
  data={'run':dict(run),'findings':findings,'reviews':reviews,'coverage':coverage,'ledger_head':head,'generated_at':now()}
  data['run'].pop('findings_json');data['run']['policy']=json.loads(data['run'].pop('policy_json'));data['run']['rules']=json.loads(data['run'].pop('rules_json'))
  if data['run']['rules'].get('kind')=='invoice':data['invoice_evidence']=invoice_evidence(e,findings)
 template='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MindTEC · Revisión de controles de datos</title><style>body{font:15px system-ui;background:#eff3f8;color:#21354c;margin:0}main{max-width:1150px;margin:auto;padding:28px}.card{background:white;padding:23px;border:1px solid #d6e0ed;border-radius:12px;margin:18px 0}.stats{display:flex;gap:20px;flex-wrap:wrap}.stats b{font-size:28px;display:block}.stats div{flex:1;min-width:160px;background:white;padding:20px;border-radius:10px}button,select{padding:10px;border:1px solid #c7d6e6;border-radius:6px;background:white;color:inherit}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:12px;border-bottom:1px solid #e1e7ef;vertical-align:top;font-size:13px}th{background:#edf3fa}.scroll{overflow:auto}code{overflow-wrap:anywhere;font-size:11px}small{color:#5d718a}a{color:#2759a0}details{margin-top:10px}h1{font-size:29px}.note{border-left:4px solid #d88c43;padding:12px 18px;background:#fff8ee}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}@media print{button,select{display:none}}</style><main><h1>Revisión de controles de datos</h1><p>Motor de auditoría · evidencia y reglas versionadas</p><div class="note">Una señal de calidad no demuestra fraude. Las enumeraciones del formulario y las mediciones son cosas distintas. Las observaciones informativas no se cuentan como incidencias que exigen corrección. Ningún dato se modifica automáticamente.</div><div class="stats" id="stats"></div><section class="card"><h2>Registros para revisar</h2><label>Mostrar <select id="scope"><option value="review">Incidencias que requieren revisión</option><option value="info">Observaciones informativas</option><option value="all">Todos los controles señalados</option></select></label><div id="rows" class="scroll"></div></section><section class="card"><h2>Cadena de evidencia</h2><div id="coverage"></div><div id="trace"></div><p>Esta página es una instantánea del último resultado aceptado. El observador actualiza su estado en health.json; un HTML guardado no acredita que el proceso siga vivo. El archivo original es privado y se conserva sin alterarlo.</p><p>Las identidades de revisión son declaradas en este entorno local. El acceso autenticado y los permisos de producción siguen pendientes de integración.</p></section></main><script id="data" type="application/json">__DATA__</script><script>const D=JSON.parse(document.getElementById('data').textContent),E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const review=D.findings.filter(f=>f.severity!=='info').length;document.getElementById('stats').innerHTML=[['Para revisión humana',review],['Informativas',D.findings.length-review],[D.run.rules.kind==='invoice'?'Líneas auditadas':'Exclusiones documentadas',D.run.rules.kind==='invoice'?(D.coverage.rows??'Sin cobertura'):(D.run.policy.exclusions||[]).length]].map(([k,v])=>'<div>'+E(k)+'<b>'+v+'</b></div>').join('');function sourceRows(ev){if(!D.invoice_evidence)return '';return [[ev.current_source_sha256,ev.source_rows,'Corte actual'],[ev.previous?.source_sha256,ev.previous?.source_rows,'Corte anterior']].map(([hash,rows,label])=>{const source=D.invoice_evidence[hash];if(!source||!rows?.length)return '';return '<details><summary>'+E(label)+' · '+E(source.provenance.filename)+' · fila '+E(rows.join(', '))+'</summary><p>SHA del corte: <code>'+E(hash)+'</code></p>'+rows.map(row=>'<p>Fila Excel '+E(row)+'</p><table>'+Object.entries(source.rows[String(row)]||{}).map(([field,value])=>'<tr><th>'+E(field)+'</th><td>'+E(value===null?'Vacío (null)':typeof value==='string'&&value===''?'Cadena vacía':value)+'</td></tr>').join('')+'</table>').join('')+'</details>'}).join('')}function change(ev){const v=ev.observed;if(!v||typeof v!=='object'||!Object.hasOwn(v,'before')||!Object.hasOwn(v,'after'))return '';return '<p><b>'+E((ev.paths||[]).join(', '))+'</b></p><p>Antes: '+E(JSON.stringify(v.before))+'<br>Después: '+E(JSON.stringify(v.after))+'</p>'}function render(){const scope=document.getElementById('scope').value,rows=D.findings.filter(f=>scope==='all'||(scope==='info'?f.severity==='info':f.severity!=='info'));document.getElementById('rows').innerHTML='<p>'+rows.length+' registros del filtro.</p><table><thead><tr><th>Control y estado</th><th>Registro y evidencia original</th><th>Explicación y revisión</th></tr></thead><tbody>'+rows.map(f=>{const r=D.reviews[f.fingerprint];return '<tr><td><b>'+E(f.title)+'</b><p>'+E(f.rule)+' · regla '+E(f.rule_version)+'</p>'+E(f.severity)+'</td><td>Registro '+E(f.evidence.record_id)+' · índice '+f.evidence.record_index+sourceRows(f.evidence)+'<details><summary>Respuestas originales</summary><pre>'+E(JSON.stringify(f.evidence,null,2))+'</pre></details><code>'+E(f.fingerprint)+'</code></td><td>'+change(f.evidence)+E(f.explanation)+'<p><b>'+E(r?r.status:'Pendiente de revisión humana')+'</b></p>'+(r?E(r.note)+'<br><small>'+E(r.actor)+' · '+E(r.at)+' · '+E(r.evidence)+'</small>':'')+'</td></tr>'}).join('')+'</tbody></table>'}document.getElementById('scope').onchange=render;document.getElementById('coverage').innerHTML=D.run.rules.kind==='invoice'?'<p>'+E(D.coverage.matched_unique_keys)+' claves emparejadas · '+E(D.coverage.ambiguous_comparison_keys)+' ambiguas · '+E(D.coverage.invoices)+' documentos.</p><p>Regla aritmética por línea: '+(D.coverage.line_arithmetic_configured?'declarada':'no configurada')+' · suma documental: '+(D.coverage.invoice_sum_configured?'declarada':'no configurada')+'. No se infieren impuestos ni completitud.</p>':'';document.getElementById('trace').innerHTML='<p>Run: <code>'+E(D.run.id)+'</code></p><p>SHA-256 original: <code>'+E(D.run.snapshot_hash)+'</code></p><p>Implementación: <code>'+E(D.run.rules.implementation_sha256)+'</code></p><p>Política: '+E(D.run.policy.version)+'</p><p>Huella de cierre: <code>'+E(D.ledger_head)+'</code></p><p>Resultado aceptado: '+E(D.run.at)+' · informe generado: '+E(D.generated_at)+'</p>'+Object.entries(D.run.rules.reference_sources||{}).map(([role,hash])=>'<p>'+E(role)+': <code>'+E(hash)+'</code></p>').join('');render();</script></html>'''
 text=template.replace('__DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c'))
 output=Path(output);output.parent.mkdir(parents=True,exist_ok=True);output.write_text(text,encoding='utf-8')
 return {'output':str(output.resolve()),'review_required':sum(f['severity']!='info' for f in findings),'informational':sum(f['severity']=='info' for f in findings),'run_id':run['id']}

if __name__=='__main__':
 import argparse
 p=argparse.ArgumentParser();p.add_argument('--runtime',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();print(json.dumps(export_report(a.runtime,a.output)))
